ALTER TABLE backup_20261012_facts_028 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON backup_20261012_facts_028 FROM anon, authenticated;

DO $mig$
DECLARE n BIGINT;
BEGIN
  SELECT count(*) INTO n FROM backup_20261012_facts_028;
  IF n <> 2854 THEN RAISE EXCEPTION '028: backup has % rows, expected 2854', n; END IF;
  DELETE FROM player_facts WHERE id IN (SELECT id FROM backup_20261012_facts_028 WHERE action_028 = 'delete');
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1687 THEN RAISE EXCEPTION '028: expected 1687 rows deleted, got %', n; END IF;
  UPDATE player_facts f SET player_id = NULL, owner_method = 'unowned by 028: ' || b.reason_028
    FROM backup_20261012_facts_028 b WHERE b.id = f.id AND b.action_028 = 'unown';
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1167 THEN RAISE EXCEPTION '028: expected 1167 rows unowned, got %', n; END IF;
END $mig$;

COMMIT;

-- --- CHECKS (run after COMMIT, alone, in a fresh session; one row) ---------------------------------
SELECT
  (SELECT count(*) FROM backup_20261012_facts_028)                                                                                    AS backup_rows,
  (SELECT count(*) FROM backup_20261012_facts_028 WHERE action_028 = 'delete')                                                        AS backup_delete,
  (SELECT count(*) FROM backup_20261012_facts_028 WHERE action_028 = 'unown')                                                         AS backup_unown,
  (SELECT count(*) FROM player_facts WHERE id IN (SELECT id FROM backup_20261012_facts_028 WHERE action_028 = 'delete'))             AS deleted_still_present,
  (SELECT count(*) FROM player_facts WHERE owner_method LIKE 'unowned by 028:%' AND player_id IS NULL)           AS unowned_rows,
  (SELECT count(*) FROM player_facts f JOIN players p ON p.id = f.player_id WHERE p.wikipedia_page_id = 2396553 AND f.fact_value = 'Manchester City') AS guardiola_man_city,
  (SELECT count(*) FROM player_facts f JOIN players p ON p.id = f.player_id WHERE p.wikipedia_page_id = 1297124 AND f.fact_type = 'played_for_team') AS kaka_clubs,
  (SELECT bool_and(relrowsecurity) FROM pg_class WHERE relname = 'backup_20261012_facts_028')                                          AS backup_rls,
  (SELECT count(*) FROM information_schema.role_table_grants WHERE table_name = 'backup_20261012_facts_028' AND grantee IN ('anon', 'authenticated')) AS backup_browser_grants;
-- EXPECTED: backup_rows = 2854; backup_delete = 1687; backup_unown = 1167; deleted_still_present = 0; unowned_rows = 1167; guardiola_man_city = 0; kaka_clubs = 2; backup_rls = true; backup_browser_grants = 0

